// DCS compatibility check (health check after a DCS update).
//
// Every patch, call and memory read in this DLL is for one DCS build (engine.h: kVerifiedBuild). On that
// build the DLL runs. On any other build it first compares the code it depends on - the sites it patches,
// the functions it calls, the code that encodes the offsets it uses and the instructions through which
// DCS reads the globals it reads (src/compat_sigs.inc, generated by tools/gen_compat.py) - with the running
// DCS. If every fingerprint is identical the update did not touch that code and the DLL runs as usual; if
// any differs, nothing is installed and the viewer tells the user the DCS version is not compatible.
//
// Every install path asks CompatOk() before touching DCS.
#pragma once

#include <string>

namespace lsodiag {

enum class CompatState { Pending = 0, Verified = 1, Matched = 2, Incompatible = 3 };

struct CompatResult {
    CompatState state = CompatState::Pending;
    std::string dcsVersion;  // DCS.exe file version
    std::string detail;      // first mismatches / what is still missing
    int checked = 0, failed = 0;
};

// Runs the comparison once every module it covers is loaded (mission running); cached from then on.
CompatResult CompatCheck();
bool CompatOk();          // Verified or Matched
std::string CompatWhy();  // "" when OK, else the reason (for install refusals)
const char* CompatStateName(CompatState s);

}  // namespace lsodiag
